using UnityEngine;\nusing UnityEngine.UI;\n\n/// <summary>\nUI component displaying rage meter.\n/// </summary>\npublic class RageBarUI : MonoBehaviour\n{\n    [SerializeField] private Image rageFillImage;\n    [SerializeField] private Image glowImage;\n    [SerializeField] private Color readyColor = Color.red;\n    [SerializeField] private Character character;\n    \n    private float currentRagePercent = 0f;\n    private float targetRagePercent = 0f;\n    private float lerpSpeed = 3f;\n    private bool isUltimateReady = false;\n    \n    private void Start()\n    {\n        if (character == null)\n        {\n            character = GetComponentInParent<Character>();\n        }\n        \n        CharacterStats.OnRageChanged += UpdateRageDisplay;\n    }\n    \n    private void OnDestroy()\n    {\n        CharacterStats.OnRageChanged -= UpdateRageDisplay;\n    }\n    \n    private void Update()\n    {\n        currentRagePercent = Mathf.Lerp(currentRagePercent, targetRagePercent, Time.deltaTime * lerpSpeed);\n        \n        if (rageFillImage != null)\n        {\n            rageFillImage.fillAmount = currentRagePercent;\n        }\n        \n        // Glow when ultimate ready\n        if (glowImage != null && character != null)\n        {\n            bool canUseUltimate = character.GetStats().CanUseUltimate();\n            if (canUseUltimate != isUltimateReady)\n            {\n                isUltimateReady = canUseUltimate;\n                glowImage.enabled = canUseUltimate;\n                \n                if (canUseUltimate)\n                {\n                    glowImage.color = readyColor;\n                }\n            }\n        }\n    }\n    \n    private void UpdateRageDisplay(float ragePercent)\n    {\n        targetRagePercent = ragePercent;\n    }\n}\n"